  footer_trusted: { en:"Trusted Sources", es:"Fuentes confiables", hi:"विश्वसनीय स्रोत", ml:"വിശ്വസ്ത സ്രോതസ്സ്", fr:"Sources fiables", ar:"مصادر موثوقة" },
  footer_legal:   { en:"For educational purposes only. Not a substitute for professional medical advice. Always consult your doctor.", es:"Solo con fines educativos. No es sustituto del consejo médico profesional.", hi:"केवल शैक्षिक उद्देश्यों के लिए। पेशेवर चिकित्सा सलाह का विकल्प नहीं।", ml:"വിദ്യാഭ്യാസ ആവശ്യങ്ങൾക്ക് മാത്രം. വൈദ്യ ഉപദേശത്തിന്റെ പകരം ഇല്ല.", fr:"À des fins éducatives uniquement. Pas un substitut à l'avis médical professionnel.", ar:"لأغراض تعليمية فقط. لا يُغني عن المشورة الطبية المتخصصة. استشر طبيبك دائماً." },
